"use client";

import { useState } from "react";

const X = (w: number) => Math.sin(2 * Math.PI * w) + 2 * w * w;
const CELLS = [1, 2, 4, 8, 32];

/** E[X | G] for the σ-algebra generated by a partition of [0, 1) into equal cells: average X on each cell. */
export function CondExpStepViz() {
  const [c, setC] = useState(1);
  const k = CELLS[c];
  const N = 400;
  const avg = Array.from({ length: k }, (_, j) => {
    let s = 0;
    for (let i = 0; i < N; i++) s += X((j + (i + 0.5) / N) / k);
    return s / N;
  });
  const mean = avg.reduce((p, v) => p + v, 0) / k;
  const X0 = 30, W = 460, Y0 = 12, H = 160, lo = -1.2, hi = 2.4;
  const x = (w: number) => X0 + w * W;
  const y = (v: number) => Y0 + H - ((v - lo) / (hi - lo)) * H;
  const ws = Array.from({ length: 201 }, (_, i) => i / 200);
  return (
    <figure className="viz">
      <div className="segmented" role="group" aria-label="cells">
        {CELLS.map((m, i) => <button key={m} type="button" aria-pressed={c === i} className={c === i ? "seg is-on" : "seg"} onClick={() => setC(i)}>{m} {m === 1 ? "cell" : "cells"}</button>)}
      </div>
      <svg viewBox="0 0 520 200" role="img" aria-label="A random variable and its conditional expectation on a partition" style={{ width: "100%", display: "block", marginTop: 8 }}>
        <line x1={X0} y1={y(0)} x2={X0 + W} y2={y(0)} style={{ stroke: "var(--border-strong)" }} />
        {Array.from({ length: k + 1 }, (_, j) => <line key={j} x1={x(j / k)} y1={Y0} x2={x(j / k)} y2={Y0 + H} style={{ stroke: "var(--grid-line)", strokeWidth: 1 }} />)}
        <polyline points={ws.map((w) => `${x(w)},${y(X(w))}`).join(" ")} style={{ fill: "none", stroke: "var(--text-muted)", strokeWidth: 1.5 }} />
        {avg.map((a, j) => <line key={j} x1={x(j / k)} y1={y(a)} x2={x((j + 1) / k)} y2={y(a)} style={{ stroke: "var(--accent)", strokeWidth: 3 }} />)}
        {[0, 0.5, 1].map((w) => <text key={w} x={x(w)} y={Y0 + H + 14} textAnchor="middle" style={{ fill: "var(--text-muted)", fontSize: 10 }}>{w}</text>)}
        <text x={X0 + 4} y={y(0) - 4} style={{ fill: "var(--text-muted)", fontSize: 10 }}>0</text>
      </svg>
      <p className="mono" style={{ fontSize: 13, fontWeight: 700 }}>
        E[X] = {mean.toFixed(3)}; average of E[X | G] = {mean.toFixed(3)}. Values of E[X | G]: {k <= 8 ? avg.map((a) => a.toFixed(2)).join(", ") : `${k} steps`}.
      </p>
      <figcaption className="viz-caption">
        Ω = [0, 1) with length as probability, and X(ω) = sin 2πω + 2ω² (grey). G is generated by splitting Ω into equal
        cells. E[X | G] (violet) is constant on each cell, equal to the average of X there. Finer information gives a
        closer copy of X, and the overall average never changes.
      </figcaption>
    </figure>
  );
}
